import * as fs from 'node:fs';
import * as path from 'node:path/posix';
import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { DateTime } from 'luxon';
import { AppLogger } from '@/common/logger/app-logger';
import { Mapping } from '@/common/mapping/interface/mapping.model';
import { PlantsResponseDto } from '@/common/subscribe/dtos/plant.response.dto';

@Injectable()
export class MappingUtilsService {
  public constructor(private readonly customLogger: AppLogger) {}

  /**
   * Loads mappings from a file in the filesystem.
   * @param filePath - The relative path to the file containing mappings.
   * @returns An array of Mapping objects loaded from the file.
   * @throws {Error} Throws an error if the file cannot be read or parsed.
   */
  public loadMappings(filePath: string): Array<Mapping> {
    const absolutePath = path.resolve(__dirname, filePath);
    try {
      const rawData = fs.readFileSync(absolutePath, 'utf8');
      return JSON.parse(rawData);
    } catch (error) {
      throw new Error(`Error loading mappings from file ${filePath}: ${error}`);
    }
  }

  /**
   * Determines if a given database is marked as "WIP" (Work In Progress).
   * @param databaseName - The name of the database.
   * @returns True if the database is "WIP", false otherwise.
   */
  public isWIP(databaseName: string | undefined): boolean {
    const context: JobsLogContext = {
      method: 'isWIP',
      service: 'MappingUtilsService',
    };
    if (databaseName) {
      return databaseName === 'WIP';
    }
    this.customLogger.error(`DB Name is missed : default isWip false`, context);
    return false;
  }

  /**
   * Checks if a field in the schema is of type timestamp.
   * @param type - The type of the field to check.
   * @returns True if the field is a timestamp, false if it is not, and undefined if the field is not found.
   */
  public findFieldWithTimestamp(type: string | undefined): boolean {
    const context: JobsLogContext = {
      method: 'findFieldWithTimestamp',
      service: 'MappingUtilsService',
    };
    try {
      if (type) {
        if (type === 'timestamp') {
          return true;
        }
        return false;
      }
      return false;
    } catch (error) {
      this.customLogger.error(
        `error in finding the type ${error.message}`,
        context,
      );
      return false;
    }
  }

  /**
   * Converts a timestamp to a Date object, considering the timezone offset if applicable.
   * @param timestamp - The timestamp to convert.
   * @param isWip - The source of the database is Wip or not.
   * @param timeZone - The timezone to consider for the conversion.
   * @returns The converted Date object, or undefined if the timestamp is invalid.
   */
  public convertTimestampToDate(
    timestamp: number,
    isWip: boolean,
    timeZone: string | undefined,
  ): Date | undefined {
    const context: JobsLogContext = {
      method: 'convertTimestampToDate',
      service: 'MappingUtilsService',
    };
    let utcDate: Date;
    if (timestamp === undefined) {
      this.customLogger.debug(`timestamp is undefined`, context);
      return undefined;
    }
    if (timestamp === 0) {
      this.customLogger.debug(`timestamp is null`, context);
      return undefined;
    }
    utcDate = new Date(timestamp);
    if (isWip) {
      utcDate = new Date(
        utcDate.getTime() + utcDate.getTimezoneOffset() * 60_000,
      );
      return utcDate;
    }
    if (timeZone) {
      // Const utcDateString = moment(timestamp).tz(timeZone).toISOString();
      const sourceDateTime = DateTime.fromMillis(timestamp, { zone: timeZone });
      const utcDateTime = sourceDateTime
        .toUTC()
        .minus({ milliseconds: sourceDateTime.offset * 60_000 });
      const utcDateString = utcDateTime.toISO();
      if (!utcDateString) {
        return undefined;
      }
      utcDate = new Date(utcDateString);
      utcDate = new Date(
        utcDate.getTime() + utcDate.getTimezoneOffset() * 60_000,
      );
    }
    return utcDate;
  }

  /**
   * Retrieves the timezone for a specific plant by its ID.
   * @param plantId - The ID of the plant.
   * @param plantList Array of list Plant
   * @returns The timezone associated with the plant, or undefined if it cannot be retrieved.
   */
  public getTimeZoneForPlant(
    plantId: number,
    plantList: Array<PlantsResponseDto>,
  ): string | undefined {
    const context: JobsLogContext = {
      method: 'getTimeZoneForPlant',
      service: 'MappingUtilsService',
    };
    try {
      const plantTimeZone = this.findPlantTimeZone(plantList, Number(plantId));

      return plantTimeZone;
    } catch (error) {
      this.customLogger.error(
        `Error retrieving time zone for plant ${plantId}: ${error.message}`,
        context,
        error.stack,
      );
      return undefined;
    }
  }

  /**
   * Finds the timezone for a specific plant by its ID from a list of plants.
   * @param plants - An array of plant response DTOs.
   * @param plantId - The ID of the plant to find.
   * @returns The timezone of the plant, or undefined if the plant is not found.
   */
  private findPlantTimeZone(
    plants: Array<PlantsResponseDto>,
    plantId: number,
  ): string | undefined {
    const plant = plants.find((plantFind) => plantFind.plantId === plantId);

    return plant ? plant.timeZone : undefined;
  }

  /**
   * Converts a hexadecimal string to a cleaned hexadecimal string (removing any non-hexadecimal characters).
   * @param hex - The hexadecimal string to clean.
   * @returns The cleaned hexadecimal string, or undefined if the input is invalid.
   */
  public hexStringToNumber(hex: string): string | undefined {
    const context: JobsLogContext = {
      method: 'hexStringToNumber',
      service: 'MappingUtilsService',
    };
    // Removing any colon (:) separators
    if (hex === undefined) {
      this.customLogger.error(`hex is undefined`, context);
      return undefined;
    }
    const cleanedHex = hex.replaceAll(/[^\da-f]/gi, '').toLowerCase();
    return cleanedHex;
  }
}

